INSERT INTO class(class_title,founder,founder_id,upload_time,content_path,class_portrait,authority,department) SELECT '【本地示例】党员学习与实践','示例编辑',1,NOW(),'','http://127.0.0.1:8080/uploads/banner-1.png',0,'电光学院' WHERE NOT EXISTS(SELECT 1 FROM class WHERE class_title='【本地示例】党员学习与实践');
INSERT INTO class(class_title,founder,founder_id,upload_time,content_path,class_portrait,authority,department) SELECT '【本地示例】积极分子成长课堂','示例编辑',1,NOW(),'','http://127.0.0.1:8080/uploads/banner-5.png',1,'电光学院' WHERE NOT EXISTS(SELECT 1 FROM class WHERE class_title='【本地示例】积极分子成长课堂');
INSERT INTO chapter(class_id,founder_id,founder,upload_time,title,type,chapter_image,chapter_video,content,chapter_portrait,duration) SELECT c.class_id,1,'示例编辑',NOW(),'学思结合：从日常行动开始',1,'','','<h2>把学习融入日常</h2><p>本章节为本地功能验证示例，不代表真实培训课程。</p><p>学习可以从一个小问题开始：在校园生活、科研实践和团队协作中，我们能做哪些具体改进？</p><h3>第一步：制定计划</h3><p>选定一个主题，安排阅读和交流时间，形成清晰的学习任务。</p><h3>第二步：联系实际</h3><p>结合自己的专业与工作，记录一个问题，提出一个可执行的改进方法。</p><h3>第三步：复盘行动</h3><p>与同伴交流实践结果，记录有效经验，持续改进。</p>','http://127.0.0.1:8080/uploads/banner-1.png',300 FROM class c WHERE c.class_title LIKE '【本地示例】%' AND NOT EXISTS(SELECT 1 FROM chapter ch WHERE ch.class_id=c.class_id AND ch.title='学思结合：从日常行动开始');
INSERT INTO class_learn_info(user_id,class_id,if_learned,learning_duration) SELECT u.id,c.class_id,0,0 FROM user u CROSS JOIN class c WHERE u.job_id IN('admin','branchadmin','member','activist') AND NOT EXISTS(SELECT 1 FROM class_learn_info l WHERE l.user_id=u.id AND l.class_id=c.class_id);
INSERT INTO learn_rate(user_id,class_id,chapter_id,ifLearned,learning_duration) SELECT u.id,c.class_id,c.chapter_id,0,0 FROM user u CROSS JOIN chapter c WHERE u.job_id IN('admin','branchadmin','member','activist') AND NOT EXISTS(SELECT 1 FROM learn_rate l WHERE l.user_id=u.id AND l.chapter_id=c.chapter_id);
